def primes_up_to(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False           # 0 and 1 are not prime
    for p in range(2, int(n ** 0.5) + 1):
        if is_prime[p]:
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False       # cross out every multiple of p
    return [x for x in range(n + 1) if is_prime[x]]

print(primes_up_to(100))
for limit in (100, 1_000, 10_000, 100_000):
    print(f"primes below {limit:>7,}: {len(primes_up_to(limit)):>5,}")

from time import perf_counter

def is_prime_slow(n):            # try every number below n
    return n > 1 and all(n % d for d in range(2, n))

def is_prime_fast(n):            # only try up to the square root
    return n > 1 and all(n % d for d in range(2, int(n ** 0.5) + 1))

n = 999_983                       # the largest prime below one million
for name, test in (("every divisor", is_prime_slow), ("up to square root", is_prime_fast)):
    start = perf_counter()
    result = test(n)
    print(f"{name:<18} prime={result}   {perf_counter() - start:.4f} s")
